const CSS = "\n:root{\n  --fire:#ff5a1f; --ember:#ffb020; --byte:#38bdf8;\n  --bg:#07080c; --bg2:#0b0e15; --panel:#11151f; --line:rgba(255,255,255,.09);\n  --text:#e9edf6; --muted:#98a2b8; --radius:18px;\n}\n*{box-sizing:border-box}\nhtml{scroll-behavior:smooth}\nbody{margin:0;background:var(--bg);color:var(--text);font-family:Inter,system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif;line-height:1.65;-webkit-font-smoothing:antialiased;overflow-x:hidden}\nh1,h2,h3,h4,.font-display{font-family:\"Space Grotesk\",Inter,sans-serif;letter-spacing:-.02em;line-height:1.1;margin:0}\na{color:inherit;text-decoration:none}\nimg{max-width:100%;display:block}\n.wrap{width:min(1160px,92vw);margin:0 auto}\n.eyebrow{font-size:.74rem;letter-spacing:.22em;text-transform:uppercase;color:var(--ember);font-weight:600;margin-bottom:14px;display:block}\nsection{padding:96px 0;position:relative}\n.muted{color:var(--muted)}\n.grad{background:linear-gradient(100deg,var(--ember),var(--fire) 45%,#ff8a3d);-webkit-background-clip:text;background-clip:text;color:transparent}\n\n.mark{position:relative;width:36px;height:36px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(140deg,var(--fire),var(--ember));color:#160a02;font-size:.8rem;font-weight:700;overflow:hidden;box-shadow:0 0 22px rgba(255,90,31,.4);flex:0 0 36px}\n.mark img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:2}\n.hero-logo{width:clamp(96px,14vw,132px);height:clamp(96px,14vw,132px);border-radius:50%;overflow:hidden;margin-bottom:26px;position:relative;background:linear-gradient(140deg,var(--fire),var(--ember));display:grid;place-items:center;box-shadow:0 0 60px -10px rgba(255,90,31,.7),0 0 0 1px rgba(255,255,255,.12)}\n.hero-logo img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:2}\n.hero-logo span{font-family:\"Space Grotesk\";font-size:1.6rem;font-weight:700;color:#160a02}\n\nheader.nav{position:fixed;top:0;left:0;right:0;z-index:100;backdrop-filter:blur(14px);background:rgba(7,8,12,.72);border-bottom:1px solid transparent;transition:.3s}\nheader.nav.scrolled{border-bottom-color:var(--line);background:rgba(7,8,12,.9)}\n.nav-inner{display:flex;align-items:center;justify-content:space-between;height:68px}\n.brand{display:flex;align-items:center;gap:11px;font-family:\"Space Grotesk\";font-weight:700;font-size:1.05rem;letter-spacing:.02em}\n.nav-links{display:flex;align-items:center;gap:24px}\n.nav-links a{font-size:.88rem;color:var(--muted);transition:.2s}\n.nav-links a:hover{color:var(--text)}\n.nav-cta{padding:9px 18px;border-radius:999px;font-size:.86rem;font-weight:600;background:linear-gradient(135deg,var(--fire),var(--ember));color:#160a02}\n.burger{display:none;background:none;border:0;color:var(--text);font-size:1.5rem;cursor:pointer}\n@media(max-width:1020px){\n  .nav-links{position:absolute;top:68px;left:0;right:0;flex-direction:column;align-items:flex-start;gap:0;background:#0a0d14;border-bottom:1px solid var(--line);padding:8px 0;max-height:0;overflow:hidden;transition:max-height .35s ease}\n  .nav-links.open{max-height:560px}\n  .nav-links a{width:100%;padding:13px 6vw;font-size:1rem}\n  .nav-links .nav-cta{margin:10px 6vw 16px;text-align:center}\n  .burger{display:block}\n}\n\n.hero{min-height:100svh;display:flex;align-items:center;padding:120px 0 80px;position:relative;overflow:hidden}\n.hero::before{content:\"\";position:absolute;inset:0;z-index:0;background:radial-gradient(700px 420px at 78% 8%,rgba(255,90,31,.22),transparent 62%),radial-gradient(620px 420px at 12% 88%,rgba(56,189,248,.16),transparent 65%),radial-gradient(900px 600px at 50% 120%,rgba(255,176,32,.10),transparent 70%)}\n.hero::after{content:\"\";position:absolute;inset:0;z-index:0;opacity:.5;background-image:linear-gradient(rgba(255,255,255,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.045) 1px,transparent 1px);background-size:64px 64px;mask-image:radial-gradient(circle at 50% 40%,#000 10%,transparent 72%);-webkit-mask-image:radial-gradient(circle at 50% 40%,#000 10%,transparent 72%)}\n.hero .wrap{position:relative;z-index:2}\n.pill{display:inline-flex;align-items:center;gap:9px;padding:7px 15px;border-radius:999px;border:1px solid rgba(255,176,32,.35);background:rgba(255,176,32,.08);font-size:.78rem;letter-spacing:.06em;color:#ffd08a;margin-bottom:26px}\n.dot{width:7px;height:7px;border-radius:50%;background:var(--ember);box-shadow:0 0 0 4px rgba(255,176,32,.18)}\nh1.hero-title{font-size:clamp(3.2rem,11vw,7.6rem);font-weight:700;letter-spacing:-.045em}\n.hero-sub{font-size:clamp(1.05rem,2.2vw,1.35rem);color:var(--muted);max-width:620px;margin:22px 0 34px}\n.hero-sub strong{color:var(--text);font-weight:600}\n.btn-row{display:flex;flex-wrap:wrap;gap:14px}\n.btn{display:inline-flex;align-items:center;gap:9px;padding:14px 26px;border-radius:999px;font-weight:600;font-size:.95rem;transition:transform .2s,box-shadow .2s,background .2s}\n.btn-primary{background:linear-gradient(135deg,var(--fire),var(--ember));color:#160a02;box-shadow:0 10px 34px -10px rgba(255,90,31,.8)}\n.btn-primary:hover{transform:translateY(-2px);box-shadow:0 16px 40px -10px rgba(255,90,31,.95)}\n.btn-ghost{border:1px solid var(--line);background:rgba(255,255,255,.03);color:var(--text)}\n.btn-ghost:hover{background:rgba(255,255,255,.07);transform:translateY(-2px)}\n\n.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;margin-top:64px}\n.stat{background:var(--bg2);padding:26px 22px}\n.stat b{display:block;font-family:\"Space Grotesk\";font-size:1.9rem;font-weight:700}\n.stat span{font-size:.82rem;color:var(--muted)}\n@media(max-width:760px){.stats{grid-template-columns:repeat(2,1fr)}}\n\n.sec-head{max-width:720px;margin-bottom:52px}\n.sec-head h2{font-size:clamp(1.9rem,4.4vw,2.9rem);font-weight:700}\n.sec-head p{color:var(--muted);margin:16px 0 0;font-size:1.02rem}\n\n.grid{display:grid;gap:20px}\n.g3{grid-template-columns:repeat(3,1fr)}\n.g2{grid-template-columns:repeat(2,1fr)}\n@media(max-width:900px){.g3{grid-template-columns:1fr 1fr}}\n@media(max-width:640px){.g3,.g2{grid-template-columns:1fr}}\n.card{background:linear-gradient(180deg,rgba(255,255,255,.045),rgba(255,255,255,.012));border:1px solid var(--line);border-radius:var(--radius);padding:28px;transition:transform .28s,border-color .28s,background .28s}\n.card:hover{transform:translateY(-4px);border-color:rgba(255,176,32,.35);background:linear-gradient(180deg,rgba(255,176,32,.07),rgba(255,255,255,.012))}\n.card h3{font-size:1.15rem;margin-bottom:10px}\n.card p{color:var(--muted);font-size:.94rem;margin:0}\n.icon{width:44px;height:44px;border-radius:12px;display:grid;place-items:center;margin-bottom:18px;background:rgba(255,90,31,.12);border:1px solid rgba(255,90,31,.28);font-size:1.2rem}\n.spec{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}\n.spec span{font-size:.74rem;padding:4px 10px;border-radius:999px;background:rgba(56,189,248,.1);border:1px solid rgba(56,189,248,.25);color:#9ad9f7}\n\n.story{display:grid;grid-template-columns:1.1fr .9fr;gap:56px;align-items:start}\n@media(max-width:900px){.story{grid-template-columns:1fr;gap:34px}}\n.story p{color:var(--muted);margin:0 0 18px}\n.quote{border-left:3px solid var(--fire);padding:6px 0 6px 22px;margin:28px 0;font-family:\"Space Grotesk\";font-size:1.15rem;color:var(--text)}\n.timeline{position:relative;padding-left:26px}\n.timeline::before{content:\"\";position:absolute;left:6px;top:6px;bottom:6px;width:1px;background:linear-gradient(var(--fire),var(--byte),transparent)}\n.tl-item{position:relative;padding-bottom:26px}\n.tl-item::before{content:\"\";position:absolute;left:-26px;top:7px;width:11px;height:11px;border-radius:50%;background:var(--bg);border:2px solid var(--ember)}\n.tl-item h4{font-size:.98rem;margin-bottom:4px}\n.tl-item p{font-size:.88rem;color:var(--muted);margin:0}\n\n.pipe{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}\n@media(max-width:900px){.pipe{grid-template-columns:1fr 1fr}}\n.step{border:1px solid var(--line);border-radius:14px;padding:20px 16px;background:var(--bg2);transition:.25s}\n.step:hover{border-color:rgba(255,176,32,.4);transform:translateY(-3px)}\n.step b{font-family:\"Space Grotesk\";font-size:.95rem;display:block;margin-bottom:6px}\n.step span{font-size:.8rem;color:var(--muted)}\n.step em{font-style:normal;font-size:.7rem;color:var(--fire);letter-spacing:.14em;display:block;margin-bottom:10px}\n\n.event{display:flex;align-items:center;gap:20px;padding:20px 24px;border:1px solid var(--line);border-radius:14px;background:var(--bg2);margin-bottom:12px;transition:.25s}\n.event:hover{border-color:rgba(56,189,248,.4);transform:translateX(4px)}\n.event .date{min-width:64px;text-align:center;border-right:1px solid var(--line);padding-right:20px}\n.event .date b{display:block;font-family:\"Space Grotesk\";font-size:1.3rem;line-height:1}\n.event .date span{font-size:.7rem;letter-spacing:.14em;color:var(--muted);text-transform:uppercase}\n.event h4{font-size:1rem;margin:0 0 2px}\n.event p{margin:0;font-size:.85rem;color:var(--muted)}\n.tag{margin-left:auto;font-size:.7rem;padding:5px 12px;border-radius:999px;background:rgba(255,176,32,.12);border:1px solid rgba(255,176,32,.3);color:#ffd08a;white-space:nowrap}\n@media(max-width:640px){.tag{display:none}}\n\n.person{text-align:center;padding:26px 18px}\n.avatar{width:76px;height:76px;border-radius:50%;margin:0 auto 16px;display:grid;place-items:center;font-family:\"Space Grotesk\";font-size:1.35rem;font-weight:700;color:#160a02;background:linear-gradient(140deg,var(--ember),var(--fire));box-shadow:0 0 0 1px rgba(255,255,255,.12),0 12px 30px -12px rgba(255,90,31,.9);overflow:hidden;position:relative}\n.avatar img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:2}\n.person h4{font-size:1rem;margin-bottom:3px}\n.person .role{font-size:.78rem;color:var(--ember);letter-spacing:.08em;text-transform:uppercase}\n.roster{display:flex;flex-wrap:wrap;gap:9px;margin-top:34px}\n.roster span{font-size:.82rem;padding:7px 14px;border-radius:999px;border:1px solid var(--line);background:rgba(255,255,255,.03);color:var(--muted)}\n\n.captains{margin-top:64px;padding-top:48px;border-top:1px solid var(--line)}\n.cap-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}\n@media(max-width:760px){.cap-grid{grid-template-columns:1fr}}\n.cap{display:flex;align-items:center;gap:22px;padding:26px 28px;border-radius:20px;border:1px solid rgba(255,176,32,.3);background:radial-gradient(400px 200px at 0% 0%,rgba(255,90,31,.18),transparent 70%),linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.01));transition:.3s}\n.cap:hover{transform:translateY(-4px);border-color:rgba(255,176,32,.6)}\n.cap .avatar{margin:0;width:68px;height:68px;flex:0 0 68px}\n.cap h4{font-size:1.15rem;margin-bottom:4px}\n.cap .role{font-size:.76rem;color:var(--ember);letter-spacing:.1em;text-transform:uppercase}\n.cap p{margin:6px 0 0;font-size:.85rem;color:var(--muted)}\n.coaches{margin-top:26px;font-size:.9rem;color:var(--muted)}\n.coaches b{color:var(--text);font-weight:600}\n\n.viewer-shell{position:relative;border-radius:22px;border:1px solid var(--line);overflow:hidden;background:radial-gradient(700px 400px at 50% 0%,rgba(56,189,248,.10),transparent 70%),#080a10}\n#cad-viewer{height:min(66vh,560px);width:100%;cursor:grab;touch-action:none}\n#cad-viewer:active{cursor:grabbing}\n#cad-viewer canvas{display:block}\n.viewer-status{position:absolute;inset:0;display:grid;place-items:center;text-align:center;padding:32px;pointer-events:none;transition:opacity .4s}\n.viewer-status.hide{opacity:0}\n.viewer-status .inner{max-width:420px}\n.viewer-status h4{font-size:1.05rem;margin-bottom:8px}\n.viewer-status p{font-size:.88rem;color:var(--muted);margin:0}\n.spinner{width:34px;height:34px;border-radius:50%;border:2px solid rgba(255,255,255,.15);border-top-color:var(--fire);margin:0 auto 18px;animation:spin 1s linear infinite}\n@keyframes spin{to{transform:rotate(360deg)}}\n\n\n.team-photo{margin:0 0 26px;border-radius:22px;overflow:hidden;border:1px solid var(--line);position:relative}\n.team-photo img{display:block;width:100%;height:auto}\n.team-photo figcaption{position:absolute;left:0;right:0;bottom:0;padding:26px 20px 14px;font-size:.8rem;color:#e8eefc;background:linear-gradient(180deg,transparent,rgba(6,8,12,.85))}\n.members{display:grid;grid-template-columns:repeat(auto-fill,minmax(104px,1fr));gap:16px;margin-top:24px}\n.member{text-align:center}\n.member img{width:74px;height:74px;border-radius:50%;object-fit:cover;border:1px solid var(--line);display:block;margin:0 auto 8px;background:#0b0e15}\n.member span{font-size:.78rem;color:var(--muted)}\n.gal{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:14px}\n.gal figure{margin:0;position:relative;border-radius:16px;overflow:hidden;border:1px solid var(--line);background:#0b0e15;aspect-ratio:4/3}\n.gal img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .5s ease}\n.gal figure:hover img{transform:scale(1.05)}\n.gal figcaption{position:absolute;inset:auto 0 0 0;padding:22px 14px 12px;font-size:.78rem;color:#dfe7f5;background:linear-gradient(180deg,transparent,rgba(6,8,12,.9))}\n.vid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:16px;margin-top:26px}\n.vid-card{position:relative;border-radius:18px;overflow:hidden;border:1px solid var(--line);background:#0b0e15;aspect-ratio:16/9;cursor:pointer}\n.vid-card video{width:100%;height:100%;object-fit:cover;display:block;background:#000}\n.vid-card .play{position:absolute;inset:0;display:grid;place-items:center;background:radial-gradient(circle at 50% 50%,rgba(255,90,31,.18),rgba(6,8,12,.55));transition:opacity .3s}\n.vid-card .play span{width:58px;height:58px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(135deg,var(--ember),var(--fire));box-shadow:0 10px 30px rgba(255,90,31,.45);font-size:1.05rem;color:#0a0c12}\n.vid-card.playing .play{opacity:0;pointer-events:none}\n.vid-card .cap{position:absolute;left:0;right:0;bottom:0;padding:20px 14px 10px;font-size:.78rem;color:#dfe7f5;background:linear-gradient(180deg,transparent,rgba(6,8,12,.9));pointer-events:none}\n.vid-card.playing .cap{display:none}\n/* --- ember loader --- */\n.orb{position:relative;width:84px;height:84px;display:grid;place-items:center;margin:0 auto 18px}\n.orb::before{content:\"\";position:absolute;inset:0;border-radius:50%;background:conic-gradient(from 0deg,rgba(255,255,255,.06),rgba(255,176,32,.25) 45%,var(--ember) 78%,var(--fire) 96%,rgba(255,90,31,0) 100%);-webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 4px),#000 calc(100% - 3px));mask:radial-gradient(farthest-side,transparent calc(100% - 4px),#000 calc(100% - 3px));animation:orbSpin 1.5s linear infinite}\n.orb .core{width:24px;height:24px;border-radius:50%;background:radial-gradient(circle at 34% 28%,#ffe0b0,var(--fire) 58%,#7d2606);box-shadow:0 0 24px rgba(255,90,31,.75),0 0 60px rgba(255,90,31,.35);animation:corePulse 1.9s ease-in-out infinite}\n.orb .sat{position:absolute;inset:0;animation:orbSpin 3.1s linear infinite}\n.orb .sat i{position:absolute;top:-2px;left:50%;width:6px;height:6px;margin-left:-3px;border-radius:50%;background:var(--byte);box-shadow:0 0 10px var(--byte)}\n.orb .sat.s2{animation-duration:4.4s;animation-direction:reverse}\n.orb .sat.s2 i{width:5px;height:5px;background:var(--ember);box-shadow:0 0 10px var(--ember)}\n@keyframes orbSpin{to{transform:rotate(360deg)}}\n@keyframes corePulse{0%,100%{transform:scale(.86);opacity:.85}50%{transform:scale(1.06);opacity:1}}\n.cad-bar{position:relative;width:min(260px,58vw);height:4px;border-radius:99px;background:rgba(255,255,255,.09);overflow:hidden;margin:16px auto 0}\n.cad-bar i{position:absolute;top:0;bottom:0;width:42%;border-radius:99px;background:linear-gradient(90deg,rgba(255,176,32,0),var(--ember),var(--fire),rgba(255,90,31,0));animation:barSweep 1.6s cubic-bezier(.45,.05,.55,.95) infinite}\n@keyframes barSweep{0%{left:-45%}100%{left:100%}}\n.cad-step{display:block;font-size:.7rem;letter-spacing:.2em;text-transform:uppercase;color:var(--ember);font-weight:600;margin-bottom:10px}\n.onshape-shell{border-radius:22px;border:1px solid var(--line);overflow:hidden;background:#080a10;margin-bottom:22px}\n.onshape-frame{position:relative;width:100%;aspect-ratio:16/10;min-height:420px}\n.onshape-frame iframe{position:absolute;inset:0;width:100%;height:100%;border:0;background:#0b0e15}\n.onshape-bar{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:14px 16px;border-top:1px solid var(--line);background:rgba(255,255,255,.02);font-size:.82rem;color:var(--muted)}\n.cad-loader{position:absolute;inset:0;z-index:5;display:grid;place-items:center;text-align:center;padding:28px;background:radial-gradient(600px 320px at 50% 38%,rgba(255,90,31,.12),transparent 72%),#080a10;transition:opacity .55s ease,visibility .55s ease}\n.cad-loader.done{opacity:0;visibility:hidden}\n.cad-loader .box{max-width:400px}\n.cad-loader h4{font-size:1.02rem;margin-bottom:6px}\n.cad-loader p{font-size:.84rem;color:var(--muted);margin:0}\n@media(prefers-reduced-motion:reduce){.orb::before,.orb .sat,.orb .core,.cad-bar i{animation:none}}\n.viewer-bar{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:14px 16px;border-top:1px solid var(--line);background:rgba(255,255,255,.02)}\n.vbtn{font-size:.82rem;padding:8px 15px;border-radius:999px;border:1px solid var(--line);background:rgba(255,255,255,.04);color:var(--text);cursor:pointer;transition:.2s;font-family:inherit}\n.vbtn:hover{background:rgba(255,255,255,.1);border-color:rgba(255,176,32,.4)}\n.vbtn.on{background:rgba(255,90,31,.18);border-color:rgba(255,90,31,.5);color:#ffc7a8}\n.viewer-hint{margin-left:auto;font-size:.76rem;color:var(--muted)}\n@media(max-width:640px){.viewer-hint{display:none}}\n\n.scan-shell{border-radius:22px;border:1px solid var(--line);overflow:hidden;background:#080a10;margin-top:22px}\n.scan-frame{position:relative;width:100%;aspect-ratio:16/10;min-height:380px}\n.scan-frame iframe{position:absolute;inset:0;width:100%;height:100%;border:0}\n.scan-bar{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:14px 16px;border-top:1px solid var(--line);background:rgba(255,255,255,.02);font-size:.82rem;color:var(--muted)}\n\n.ig-head{display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:34px}\n.ig-badge{width:52px;height:52px;border-radius:16px;display:grid;place-items:center;background:linear-gradient(135deg,#f9ce34,#ee2a7b 50%,#6228d7);font-size:1.4rem}\n.reel-strip{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\n@media(max-width:900px){.reel-strip{grid-template-columns:1fr 1fr}}\n.reel{position:relative;aspect-ratio:9/16;border-radius:20px;overflow:hidden;border:1px solid var(--line);background:linear-gradient(160deg,#1a1220,#0b0e15);display:block;transition:.3s}\n.reel:hover{transform:translateY(-5px);border-color:rgba(238,42,123,.5)}\n.reel video{width:100%;height:100%;object-fit:cover}\n.reel .ph{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:flex-end;padding:18px;background:radial-gradient(300px 200px at 50% 20%,rgba(238,42,123,.22),transparent 70%)}\n.reel .ph .glyph{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font-size:2rem;opacity:.5}\n.reel .ph b{font-size:.85rem;position:relative}\n.reel .ph span{font-size:.74rem;color:var(--muted);position:relative}\n\n.rail{position:fixed;right:18px;top:50%;transform:translateY(-50%);width:196px;z-index:60;display:none}\n@media(min-width:1560px){.rail{display:block}}\n.rail-inner{display:flex;flex-direction:column;gap:14px}\n.rail .reel{aspect-ratio:9/16;border-radius:18px}\n.rail-label{font-size:.66rem;letter-spacing:.2em;text-transform:uppercase;color:var(--muted);text-align:center;margin-bottom:2px}\n.rail-scroll{max-height:74vh;overflow:hidden;mask-image:linear-gradient(transparent,#000 8%,#000 92%,transparent);-webkit-mask-image:linear-gradient(transparent,#000 8%,#000 92%,transparent)}\n.rail-track{display:flex;flex-direction:column;gap:14px;animation:railScroll 46s linear infinite}\n.rail-track:hover{animation-play-state:paused}\n@keyframes railScroll{from{transform:translateY(0)}to{transform:translateY(-50%)}}\n\n.join{display:grid;grid-template-columns:1fr 1fr;gap:20px}\n@media(max-width:820px){.join{grid-template-columns:1fr}}\n.join-card{border:1px solid var(--line);border-radius:20px;padding:32px;background:linear-gradient(180deg,rgba(255,255,255,.045),rgba(255,255,255,.012))}\n.join-card h3{font-size:1.2rem;margin-bottom:12px}\n.join-card p{color:var(--muted);font-size:.94rem;margin:0 0 18px}\n.join-card ol{margin:0;padding-left:20px;color:var(--muted);font-size:.94rem}\n.join-card li{margin-bottom:10px}\n.join-card li b{color:var(--text)}\n\n.donate{border-radius:26px;padding:56px 44px;position:relative;overflow:hidden;border:1px solid rgba(255,176,32,.28);background:radial-gradient(600px 300px at 85% 0%,rgba(255,90,31,.22),transparent 65%),linear-gradient(180deg,#141018,#0b0e15)}\n.donate h2{font-size:clamp(1.8rem,4vw,2.6rem);margin-bottom:16px}\n.donate p{color:var(--muted);max-width:560px;margin:0 0 28px}\n@media(max-width:640px){.donate{padding:38px 24px}}\n\n.contact-card{display:flex;align-items:center;gap:14px;padding:18px 20px;border:1px solid var(--line);border-radius:14px;background:var(--bg2);transition:.25s}\n.contact-card:hover{border-color:rgba(255,176,32,.4);transform:translateY(-3px)}\n.contact-card .icon{margin:0;width:38px;height:38px;font-size:1rem}\n.contact-card b{display:block;font-size:.9rem}\n.contact-card span{font-size:.82rem;color:var(--muted);word-break:break-all}\n\nfooter{border-top:1px solid var(--line);padding:44px 0;background:var(--bg2)}\n.foot{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap;font-size:.85rem;color:var(--muted)}\n.foot a:hover{color:var(--ember)}\n\n.reveal{opacity:0;transform:translateY(22px);transition:opacity .7s cubic-bezier(.2,.7,.2,1),transform .7s cubic-bezier(.2,.7,.2,1)}\n.reveal.in{opacity:1;transform:none}\n@media(prefers-reduced-motion:reduce){.reveal{opacity:1;transform:none;transition:none}.rail-track{animation:none}}\n\n.nav-links a.active{color:var(--text);position:relative}\n.nav-links a.active::after{content:\"\";position:absolute;left:0;right:0;bottom:-6px;height:2px;border-radius:2px;background:linear-gradient(90deg,var(--ember),var(--fire))}\n\n.members{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:16px;margin-top:26px}\n.member{display:flex;flex-direction:column;border-radius:18px;overflow:hidden;border:1px solid var(--line);background:#0b0e15;cursor:pointer;transition:transform .3s ease,border-color .3s ease,box-shadow .3s ease}\n.member:hover{transform:translateY(-4px);border-color:rgba(255,90,31,.5);box-shadow:0 18px 40px rgba(0,0,0,.45)}\n.member img{width:100%;aspect-ratio:1/1;object-fit:cover;display:block;background:#111621}\n.member.open img{aspect-ratio:auto;max-height:520px;object-fit:contain}\n.member .nm{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:12px 14px;font-size:.88rem;font-weight:600;color:var(--text);border-top:1px solid var(--line)}\n.member .nm::after{content:\"+\";color:var(--ember);font-size:1.05rem;line-height:1}\n.member.open .nm::after{content:\"−\"}\n.member .bio{max-height:0;overflow:hidden;transition:max-height .35s ease;padding:0 14px;font-size:.8rem;color:var(--muted)}\n.member.open .bio{max-height:120px;padding:0 14px 14px}\n@media(max-width:560px){.members{grid-template-columns:repeat(auto-fill,minmax(150px,1fr))}}\n.gal figure{cursor:zoom-in}\n.lb{position:fixed;inset:0;z-index:300;display:none;place-items:center;padding:24px;background:rgba(4,6,10,.94)}\n.lb.on{display:grid}\n.lb img{max-width:min(1200px,94vw);max-height:86vh;border-radius:14px;border:1px solid var(--line);box-shadow:0 30px 80px rgba(0,0,0,.65)}\n.lb .cap{position:absolute;bottom:22px;left:0;right:0;text-align:center;font-size:.85rem;color:#cfd8e8}\n.lb .x{position:absolute;top:16px;right:22px;font-size:1.7rem;color:#fff;cursor:pointer;line-height:1;opacity:.75}\n.member img{aspect-ratio:4/5}\n.tiers{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px;margin-top:26px}\n.tier{position:relative;border-radius:20px;border:1px solid var(--line);background:linear-gradient(180deg,#0d1420,#080a10);padding:28px 22px 24px;overflow:hidden;transition:transform .3s ease,border-color .3s ease}\n.tier:hover{transform:translateY(-4px);border-color:rgba(255,255,255,.18)}\n.tier::before{content:\"\";position:absolute;top:0;left:0;right:0;height:3px;background:var(--tier-color,#666)}\n.tier.bronze{--tier-color:#c07a4a}\n.tier.silver{--tier-color:#b9c4d2}\n.tier.gold{--tier-color:#e8b23a}\n.tier.platinum{--tier-color:#7fd4ff}\n.tier-name{display:block;font-size:.72rem;letter-spacing:.2em;text-transform:uppercase;color:var(--tier-color);font-weight:700;margin-bottom:8px}\n.tier-price{display:block;font-size:1.9rem;font-weight:700;color:var(--text);margin-bottom:18px;line-height:1}\n.tier ul{list-style:none;padding:0;margin:0;display:grid;gap:10px}\n.tier li{position:relative;padding-left:20px;font-size:.86rem;color:var(--muted);line-height:1.45}\n.tier li::before{content:\"\";position:absolute;left:0;top:.55em;width:8px;height:8px;border-radius:50%;background:var(--tier-color);opacity:.85}\n.vid{grid-template-columns:repeat(auto-fill,minmax(260px,1fr));align-items:start}\n.vid-card{aspect-ratio:auto;min-height:180px;background:#000}\n.vid-card video{width:100%;height:auto;max-height:72vh;object-fit:contain;display:block;background:#000}\n.vid-card .play{position:absolute;inset:0}\n.vid-card .cap{position:absolute;left:0;right:0;bottom:0}\n.lb{position:fixed;top:0;left:0;width:100vw;height:100vh;z-index:99999;display:none;align-items:center;justify-content:center;padding:24px;background:rgba(4,6,10,.96)}\n.lb.on{display:flex}\n.lb img{max-width:92vw;max-height:82vh;width:auto;height:auto;border-radius:12px;border:1px solid var(--line);box-shadow:0 30px 80px rgba(0,0,0,.7);object-fit:contain}\n.lb .x{position:fixed;top:18px;right:22px;width:46px;height:46px;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.22);color:#fff;font-size:1.5rem;line-height:1;cursor:pointer;z-index:100000;padding:0}\n.lb .x:hover{background:rgba(255,255,255,.2)}\n.lb .cap{position:fixed;left:0;right:0;bottom:20px;text-align:center;font-size:.85rem;color:#cfd8e8;padding:0 24px}\nbody.lb-open{overflow:hidden}";
