const HEAD = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Firebytes — FTC Team 32734 | BASIS Phoenix</title>\n<meta name=\"description\" content=\"Firebytes is FIRST Tech Challenge Team 32734 from BASIS Phoenix, Arizona. Meet The Phoenix, explore our robot in 3D, and support the team.\">\n<meta property=\"og:title\" content=\"Firebytes — FTC Team 32734\">\n<meta property=\"og:description\" content=\"Second-year robotics team from BASIS Phoenix, Arizona. Rookie-season Judges Choice Award winners and State Championship qualifiers.\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<link rel=\"stylesheet\" href=\"/styles.css\">\n</head>\n<body>\n";

const PAGES = {"/":{"title":"Firebytes — FTC Team 32734 | BASIS Phoenix","desc":"Firebytes is FIRST Tech Challenge Team 32734 from BASIS Phoenix, Arizona. Meet The Phoenix and support the team.","body":["top","about","season"]},"/robot":{"title":"The Robot — Firebytes FTC 32734","desc":"Inside The Phoenix: drivetrain, scoring mechanism, and the build pipeline behind our FTC robot.","body":["robot","pipeline"]},"/cad":{"title":"3D Model — Firebytes FTC 32734","desc":"Explore The Phoenix in 3D, straight from our CAD export.","body":["cad"],"viewer":true},"/outreach":{"title":"Outreach — Firebytes FTC 32734","desc":"CAD workshops, FLL mentoring, and the events where we spread STEM in Arizona.","body":["outreach","instagram"]},"/team":{"title":"Team — Firebytes FTC 32734","desc":"Meet the 18 students behind Firebytes, FTC Team 32734 at BASIS Phoenix.","body":["team"]},"/gallery":{"title":"Gallery — Firebytes FTC 32734","desc":"Competitions, outreach events, and build nights from our season.","body":["gallery"]},"/join":{"title":"Join & Support — Firebytes FTC 32734","desc":"Sponsor Firebytes, join the team, or get in touch.","body":["join","donate","contact"]}};
const SECTIONS = {"top":"<section id=\"top\">\n  <div class=\"wrap\" style=\"padding:104px 0 72px;text-align:center\">\n    <span class=\"mark\" style=\"width:104px;height:104px;flex:0 0 104px;font-size:1.5rem;margin:0 auto 28px\"><img src=\"https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/team%20logo.png\" alt=\"Firebytes\" onerror=\"this.style.display='none'\"><span>FB</span></span>\n    <span class=\"eyebrow\">FTC Team 32734 &middot; BASIS Phoenix, Arizona</span>\n    <h1 style=\"font-size:clamp(2.4rem,7vw,4.4rem);line-height:1.02;margin:14px 0 18px\">Firebytes</h1>\n    <p style=\"max-width:640px;margin:0 auto 32px;color:var(--muted);font-size:1.05rem\">A student-built robotics team from BASIS Phoenix. Rookie-season Judges' Choice Award winners, State Championship qualifiers, and builders of The Phoenix.</p>\n    <div style=\"display:flex;gap:12px;justify-content:center;flex-wrap:wrap\">\n      <a class=\"btn btn-primary\" href=\"/robot\">Meet The Phoenix</a>\n      <a class=\"btn btn-ghost\" href=\"/cad\">View it in 3D</a>\n      <a class=\"btn btn-ghost\" href=\"/join\">Support the team</a>\n    </div>\n  </div>\n</section>","about":"<section id=\"about\">\n  <div class=\"wrap\">\n    <div class=\"story\">\n      <div class=\"reveal\">\n        <span class=\"eyebrow\">Our story</span>\n        <h2 style=\"font-size:clamp(1.9rem,4.4vw,2.9rem);margin-bottom:22px\">Built from scratch,<br>driven by iteration.</h2>\n        <p>Firebytes is the robotics team at BASIS Phoenix, now in our second season. Our rookie year started with almost nothing: a goBILDA starter bot, a box of donated structural parts from a team that never competed, and a group of students who had never built a competition robot before.</p>\n        <p>We replaced the starter drivetrain with mecanum wheels, then rebuilt the intake, launcher, and electronics around it. Parts delays and registration hurdles cost us months, so we compressed the entire build into the two weeks before our first qualifier &mdash; and finished the robot the morning of the event.</p>\n        <div class=\"quote\">&ldquo;We won the Judges&rsquo; Choice Award and qualified for the State Championship in our rookie season.&rdquo;</div>\n        <p>Since then we have kept iterating: new odometry pods, a Limelight camera for autonomous alignment, a redesigned single-shaft intake, and a rebalanced control scheme based on what our drivers learned under match pressure. This season we are building on all of it.</p>\n      </div>\n      <div class=\"reveal\">\n        <span class=\"eyebrow\">Season timeline</span>\n        <div class=\"timeline\">\n          <div class=\"tl-item\"><h4>Rookie formation</h4><p>Team founded at BASIS Phoenix; starter bot and donated parts acquired.</p></div>\n          <div class=\"tl-item\"><h4>Prototype</h4><p>Mecanum drivetrain swap, custom intake and launcher development.</p></div>\n          <div class=\"tl-item\"><h4>Build sprint</h4><p>Robot assembled in two weeks before the Queen Creek Qualifier.</p></div>\n          <div class=\"tl-item\"><h4>Qualifier</h4><p>Judges&rsquo; Choice Award &mdash; and a berth at the State Championship.</p></div>\n          <div class=\"tl-item\"><h4>Optimization</h4><p>Odometry, Limelight vision, and a refined launcher for State.</p></div>\n          <div class=\"tl-item\"><h4>Second season</h4><p>Three qualifiers booked across Arizona. The build continues.</p></div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>","robot":"<section id=\"robot\" style=\"background:linear-gradient(180deg,transparent,rgba(255,255,255,.02),transparent)\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\">\n      <span class=\"eyebrow\">The robot</span>\n      <h2>Meet <span class=\"grad\">The Phoenix</span>.</h2>\n      <p>Named for the bird on our crest. Nothing on this robot was designed in isolation &mdash; each mechanism was prototyped on the bot, tested in matches, then kept, changed, or cut.</p>\n    </div>\n    <div class=\"grid g3\">\n      <div class=\"card reveal\">\n        <div class=\"icon\">&#9881;</div>\n        <h3>Mecanum drivetrain</h3>\n        <p>Four mecanum wheels, each driven by a 312 RPM motor through a miter gear. Omnidirectional motion and fast rotation give us an edge over a slower tank drive.</p>\n        <div class=\"spec\"><span>Omnidirectional</span><span>312 RPM</span><span>Miter gears</span></div>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"icon\">&#128260;</div>\n        <h3>Boot-wheel intake</h3>\n        <p>Seven 96 mm boot wheels on a single Rex shaft, chain-driven by a 312 RPM motor. The wheels interlock with the holes in the artifacts for a far more reliable grab than surface contact alone.</p>\n        <div class=\"spec\"><span>7 boot wheels</span><span>Gecko-wheel feed</span><span>Compliance</span></div>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"icon\">&#127919;</div>\n        <h3>Flywheel launcher</h3>\n        <p>A 3D-printed fixed hood centers each artifact and holds a consistent 45&deg; compression. Two hogback wheels plus steel flywheels add rotational inertia for higher throughput and shorter cycle times.</p>\n        <div class=\"spec\"><span>6000 RPM</span><span>Fixed hood</span><span>Servo gate</span></div>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"icon\">&#128377;</div>\n        <h3>Driver controls</h3>\n        <p>Two Logitech F310 controllers split motion from scoring. Translation and rotation live on controller one, inspired by modern console games; flywheel, lever, and feeder live on controller two.</p>\n        <div class=\"spec\"><span>Split layout</span><span>20% endgame speed</span><span>AprilTag align</span></div>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"icon\">&#128225;</div>\n        <h3>Autonomous positioning</h3>\n        <p>Odometry pods and a Limelight camera let the robot localize and align without human input &mdash; the biggest upgrade we made between our qualifier and the State Championship.</p>\n        <div class=\"spec\"><span>Odometry</span><span>Limelight</span><span>AprilTag</span></div>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"icon\">&#128230;</div>\n        <h3>Field-ready logistics</h3>\n        <p>A rolling toolbox and modular organizer keep every part sorted by type. The whole workstation packs into a car in minutes, so we can build nearly anywhere.</p>\n        <div class=\"spec\"><span>Inventoried</span><span>Modular</span><span>Portable</span></div>\n      </div>\n    </div>\n  </div>\n</section>","cad":"<section id=\"cad\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\">\n      <span class=\"eyebrow\">Explore in 3D</span>\n      <h2>Spin The Phoenix around.</h2>\n      <p>The real chassis, rendered live in your browser from our CAD export. Drag to rotate, scroll or pinch to zoom &mdash; or <a href=\"https://cad.onshape.com/documents/556d4883d8e09b90ad31a253/w/ba447c76dfd1573ef4bf9d6e/e/abb6b9b8efeededf5272f045\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--ember)\">open the full assembly in Onshape</a>.</p>\n    </div>\n\n    \n    <div class=\"viewer-shell reveal\">\n      <div id=\"cad-viewer\"></div>\n      <div class=\"viewer-status\" id=\"cad-status\">\n        <div class=\"inner\">\n          <div class=\"orb\" id=\"cad-spinner\"><span class=\"core\"></span><span class=\"sat\"><i></i></span><span class=\"sat s2\"><i></i></span></div>\n          <span class=\"cad-step\">STEP viewer</span>\n          <h4 id=\"cad-title\">Loading 3D engine</h4>\n          <p id=\"cad-msg\">Preparing the viewer.</p>\n          <div class=\"cad-bar\"><i></i></div>\n        </div>\n      </div>\n      <div class=\"viewer-bar\">\n        <button class=\"vbtn on\" id=\"cad-rotate\">Auto-rotate</button>\n        <button class=\"vbtn\" id=\"cad-reset\">Reset view</button>\n        <button class=\"vbtn\" id=\"cad-wire\">Wireframe</button>\n        <a class=\"vbtn\" style=\"margin:0;text-decoration:none\" href=\"https://cad.onshape.com/documents/556d4883d8e09b90ad31a253/w/ba447c76dfd1573ef4bf9d6e/e/abb6b9b8efeededf5272f045\" target=\"_blank\" rel=\"noopener\">Open The Phoenix in Onshape</a><input type=\"file\" id=\"cad-file\" accept=\".step,.stp\" hidden>\n        <span class=\"viewer-hint\">Drag to orbit &middot; Scroll to zoom</span>\n      </div>\n    </div>\n\n    <div class=\"scan-shell reveal\">\n      <div class=\"scan-frame\">\n        <iframe src=\"https://lumalabs.ai/embed/0128CB88-E1FA-493C-92A7-5340178D7012?mode=sparkles&background=%2307080c&color=%23ffffff&showTitle=true&loadBg=true&logoPosition=bottom-left&infoPosition=bottom-right&showMenu=false\" title=\"3D scan of The Phoenix\" allow=\"fullscreen; xr-spatial-tracking\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>\n      </div>\n      <div class=\"scan-bar\">\n        <span>Photogrammetry scan of The Phoenix, captured with Luma AI.</span>\n        <a class=\"btn btn-ghost\" style=\"margin-left:auto;padding:8px 16px;font-size:.8rem\" href=\"https://lumalabs.ai/capture/0128CB88-E1FA-493C-92A7-5340178D7012\" target=\"_blank\" rel=\"noopener\">Open full screen &rarr;</a>\n      </div>\n    </div>\n  </div>\n</section>","pipeline":"<section id=\"pipeline\" style=\"background:linear-gradient(180deg,transparent,rgba(255,255,255,.02),transparent)\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\">\n      <span class=\"eyebrow\">Engineering process</span>\n      <h2>The Integrated Design Pipeline</h2>\n      <p>Most teams brainstorm, CAD, analyze, then build. We found we learn faster by testing ideas on the actual robot &mdash; so each step feeds directly into the next instead of standing alone.</p>\n    </div>\n    <div class=\"pipe reveal\">\n      <div class=\"step\"><em>01</em><b>Brainstorm</b><span>Identify the problem and sketch options.</span></div>\n      <div class=\"step\"><em>02</em><b>Rapid prototype</b><span>Build it on the bot, not just on screen.</span></div>\n      <div class=\"step\"><em>03</em><b>Test in context</b><span>Measure it against real match conditions.</span></div>\n      <div class=\"step\"><em>04</em><b>Decide</b><span>Keep, modify, or remove the mechanism.</span></div>\n      <div class=\"step\"><em>05</em><b>Iterate</b><span>Fold the result into the current design.</span></div>\n    </div>\n    <p class=\"muted reveal\" style=\"margin-top:26px;max-width:760px\">Our odometry pods and Limelight arrived six days before the State Championship. Because the pipeline is built for fast physical iteration, they went from unboxing to a working autonomous routine in under a week.</p>\n  </div>\n</section>","season":"<section id=\"season\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\">\n      <span class=\"eyebrow\">Season schedule</span>\n      <h2>Where to find us</h2>\n      <p>Three qualifying tournaments across Arizona this season. Come say hello &mdash; we love talking to other teams and to anyone curious about robotics.</p>\n    </div>\n    <div class=\"reveal\">\n      <div class=\"event\">\n        <div class=\"date\"><b>NOV 7</b><span>Qualifier 1</span></div>\n        <div><h4>Quail Qualifier</h4><p>Arizona FIRST Tech Challenge qualifying tournament</p></div>\n        <span class=\"tag\">Completed</span>\n      </div>\n      <div class=\"event\">\n        <div class=\"date\"><b>JAN 16</b><span>Qualifier 2</span></div>\n        <div><h4>Ironwood Qualifier</h4><p>Arizona FIRST Tech Challenge qualifying tournament</p></div>\n        <span class=\"tag\">Upcoming</span>\n      </div>\n      <div class=\"event\">\n        <div class=\"date\"><b>FEB 6</b><span>Qualifier 3</span></div>\n        <div><h4>Copper Qualifier</h4><p>Arizona FIRST Tech Challenge qualifying tournament</p></div>\n        <span class=\"tag\">Upcoming</span>\n      </div>\n    </div>\n  </div>\n</section>","outreach":"<section id=\"outreach\" style=\"background:linear-gradient(180deg,transparent,rgba(255,255,255,.02),transparent)\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\">\n      <span class=\"eyebrow\">Outreach</span>\n      <h2>Robotics does not stop at our build room.</h2>\n      <p>Our mission is to spread awareness for robotics and STEM. In our rookie season we had a lot to learn &mdash; and a lot to give back.</p>\n    </div>\n    <div class=\"grid g3\">\n      <div class=\"card reveal\">\n        <div class=\"icon\">&#128218;</div>\n        <h3>FTC Kickoff CAD workshop</h3>\n        <p>We hosted an outreach event at FTC Kickoff teaching CAD basics for FTC &mdash; introducing roughly 60 students to what CAD is and how to model in Onshape, many of them complete novices.</p>\n        <div class=\"spec\"><span>~60 students</span><span>Onshape</span><span>Beginners</span></div>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"icon\">&#129513;</div>\n        <h3>Mentoring FLL 62351</h3>\n        <p>We work with the middle school FIRST LEGO League team at our school, helping with robot construction and programming while building a pathway from middle school into high school robotics.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"icon\">&#129309;</div>\n        <h3>Learning from veterans</h3>\n        <p>Visits to established programs at BASIS Goodyear and Brophy College Preparatory gave us technical guidance and inspiration we could not have found on our own.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"icon\">&#128227;</div>\n        <h3>Building a presence</h3>\n        <p>Our social media documented member spotlights, build progress, and mentoring moments &mdash; reaching students across BASIS Phoenix and beyond.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"icon\">&#127793;</div>\n        <h3>Three future members</h3>\n        <p>We recruited three incoming members and have already taught them CAD modeling, the REV Hardware Client, and hands-on robot modifications.</p>\n      </div>\n      <div class=\"card reveal\">\n        <div class=\"icon\">&#128176;</div>\n        <h3>Sustainable funding</h3>\n        <p>We track every purchase in a categorized spreadsheet and are building fundraising capacity so the team outlasts its founding members.</p>\n      </div>\n    </div>\n  </div>\n\n  \n</section>","team":"<section id=\"team\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\">\n      <span class=\"eyebrow\">Leadership</span>\n      <h2>The people behind The Phoenix</h2>\n      <p>Student-led, coach-supported. Every subsystem has an owner and every owner answers to the team.</p>\n    </div>\n\n    <figure class=\"team-photo reveal\">\n      <img src=\"https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/grouprobotics%20phoito%20of%20entire%20team%20main%20one.jpeg\" alt=\"Firebytes, FTC Team 32734\" loading=\"lazy\" onerror=\"this.closest('figure').style.display='none'\">\n      <figcaption>Firebytes &middot; FTC Team 32734 &middot; BASIS Phoenix</figcaption>\n    </figure>\n    <div class=\"grid g3\">\n      <div class=\"card person reveal\"><div class=\"avatar\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Fpaul.png&w=200&output=webp&q=82\" alt=\"Paul Hunsinger\" onerror=\"this.style.display='none'\">P</div><h4>Paul Hunsinger</h4><span class=\"role\">Build Lead</span></div>\n      <div class=\"card person reveal\"><div class=\"avatar\"><img src=\"/team/surya.jpg\" alt=\"Surya Sreenivasan\" onerror=\"this.style.display='none'\">S</div><h4>Surya Sreenivasan</h4><span class=\"role\">Programming Lead</span></div>\n      <div class=\"card person reveal\"><div class=\"avatar\"><img src=\"/team/sriram.jpg\" alt=\"Sriram Esakkiappan\" onerror=\"this.style.display='none'\">S</div><h4>Sriram Esakkiappan</h4><span class=\"role\">CAD Lead</span></div>\n      <div class=\"card person reveal\"><div class=\"avatar\"><img src=\"https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/soha.jpeg\" alt=\"Soha Mansoori\" onerror=\"this.style.display='none'\">S</div><h4>Soha Mansoori</h4><span class=\"role\">Outreach Lead</span></div>\n      <div class=\"card person reveal\"><div class=\"avatar\"><img src=\"/team/sahishnu.jpg\" alt=\"Sahishnu Iyyapillai\" onerror=\"this.style.display='none'\">S</div><h4>Sahishnu Iyyapillai</h4><span class=\"role\">Operations Manager</span></div>\n      <div class=\"card person reveal\"><div class=\"avatar\"><img src=\"/team/aahan.jpg\" alt=\"Aahan Saxena\" onerror=\"this.style.display='none'\">A</div><h4>Aahan Saxena</h4><span class=\"role\">Social Media Lead</span></div>\n    </div>\n\n    <div class=\"captains reveal\">\n      <span class=\"eyebrow\">Captains</span>\n      <div class=\"cap-grid\">\n        <div class=\"cap\">\n          <div class=\"avatar\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Fpaul.png&w=200&output=webp&q=82\" alt=\"Paul Hunsinger\" onerror=\"this.style.display='none'\">P</div>\n          <div>\n            <h4>Paul Hunsinger</h4>\n            <span class=\"role\">Captain &middot; Build Lead</span>\n            <p>Leads mechanical design and fabrication, and keeps the build schedule on track.</p>\n          </div>\n        </div>\n        <div class=\"cap\">\n          <div class=\"avatar\"><img src=\"/team/surya.jpg\" alt=\"Surya Sreenivasan\" onerror=\"this.style.display='none'\">S</div>\n          <div>\n            <h4>Surya Sreenivasan</h4>\n            <span class=\"role\">Captain &middot; Programming Lead</span>\n            <p>Owns autonomous routines, driver controls, and the team&rsquo;s software stack.</p>\n          </div>\n        </div>\n      </div>\n      <p class=\"coaches\"><b>Coaches:</b> Ms. Kelsey Cooper and Ms. Melita Hunsinger</p>\n    </div>\n\n    <div class=\"reveal\">\n      <span class=\"eyebrow\" style=\"margin-top:56px\">Team roster</span>\n      <div class=\"roster\">\n        <span>Aahan Saxena</span><span>Aarav Khanna</span><span>Arnav Bandi</span><span>Arnav Chhabra</span>\n        <span>Bhuvan Potlapalli</span><span>Harshal Sharma</span><span>Jensen Prasad</span><span>Lucky Tana</span>\n        <span>Paul Hunsinger</span><span>Pranit Kumar</span><span>Rimsha Khan</span><span>Soha Mansoori</span>\n        <span>Surya Sreenivasan</span><span>Srikar Kollu</span><span>Sahishnu Iyyapillai</span><span>Arman Das</span>\n        <span>Sriram Esakappian</span><span>Peter Kwong</span>\n      </div>\n      <div class=\"members reveal\">\n        <div class=\"member\" onclick=\"this.classList.toggle('open')\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com/suryasreenivasan/firebytes/main/aarav.png.jpg&w=520&output=webp&q=82\" alt=\"Aarav\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/aarav.png.jpg'\"><div class=\"nm\">Aarav</div><div class=\"bio\">Team Member &middot; FTC Team 32734</div></div>\n        <div class=\"member\" onclick=\"this.classList.toggle('open')\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com/suryasreenivasan/firebytes/main/arnav.jpeg&w=520&output=webp&q=82\" alt=\"Arnav Chhabra\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/arnav.jpeg'\"><div class=\"nm\">Arnav Chhabra</div><div class=\"bio\">Team Member &middot; FTC Team 32734</div></div>\n        <div class=\"member\" onclick=\"this.classList.toggle('open')\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com/suryasreenivasan/firebytes/main/bhuvan.jpeg&w=520&output=webp&q=82\" alt=\"Bhuvan\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/bhuvan.jpeg'\"><div class=\"nm\">Bhuvan</div><div class=\"bio\">Team Member &middot; FTC Team 32734</div></div>\n        <div class=\"member\" onclick=\"this.classList.toggle('open')\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com/suryasreenivasan/firebytes/main/harshal.jpeg&w=520&output=webp&q=82\" alt=\"Harshal\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/harshal.jpeg'\"><div class=\"nm\">Harshal</div><div class=\"bio\">Team Member &middot; FTC Team 32734</div></div>\n        <div class=\"member\" onclick=\"this.classList.toggle('open')\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com/suryasreenivasan/firebytes/main/lakshith.png.jpeg&w=520&output=webp&q=82\" alt=\"Lucky\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/lakshith.png.jpeg'\"><div class=\"nm\">Lucky</div><div class=\"bio\">Team Member &middot; FTC Team 32734</div></div>\n        <div class=\"member\" onclick=\"this.classList.toggle('open')\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com/suryasreenivasan/firebytes/main/peter.jpeg&w=520&output=webp&q=82\" alt=\"Peter\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/peter.jpeg'\"><div class=\"nm\">Peter</div><div class=\"bio\">Team Member &middot; FTC Team 32734</div></div>\n        <div class=\"member\" onclick=\"this.classList.toggle('open')\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com/suryasreenivasan/firebytes/main/pranit.png.jpeg&w=520&output=webp&q=82\" alt=\"Pranit\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/pranit.png.jpeg'\"><div class=\"nm\">Pranit</div><div class=\"bio\">Team Member &middot; FTC Team 32734</div></div>\n        <div class=\"member\" onclick=\"this.classList.toggle('open')\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com/suryasreenivasan/firebytes/main/soha.jpeg&w=520&output=webp&q=82\" alt=\"Soha\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/soha.jpeg'\"><div class=\"nm\">Soha</div><div class=\"bio\">Outreach Lead &middot; FTC Team 32734</div></div>\n        <div class=\"member\" onclick=\"this.classList.toggle('open')\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com/suryasreenivasan/firebytes/main/paul.png&w=520&output=webp&q=82\" alt=\"Paul\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/paul.png'\"><div class=\"nm\">Paul</div><div class=\"bio\">Build Lead &middot; FTC Team 32734</div></div>\n        <div class=\"member\" onclick=\"this.classList.toggle('open')\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com/suryasreenivasan/firebytes/main/rimshaw.jpeg&w=520&output=webp&q=82\" alt=\"Rimsha\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/rimshaw.jpeg'\"><div class=\"nm\">Rimsha</div><div class=\"bio\">Team Member &middot; FTC Team 32734</div></div>\n      </div>\n\n    </div>\n  </div>\n</section>","gallery":"<section id=\"gallery\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\">\n      <span class=\"eyebrow\">Gallery</span>\n      <h2>Season in pictures</h2>\n      <p>Competitions, outreach events, and the late nights in between.</p>\n    </div>\n    <div class=\"gal\">\n      <figure class=\"reveal\"><img src=\"https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/32734%20at%20az%20states.jpeg\" alt=\"Team 32734 at Arizona State\" loading=\"lazy\"><figcaption>Team 32734 at Arizona State</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/all%20basis%20schools%20at%20az%20states.jpeg\" alt=\"BASIS schools at AZ States\" loading=\"lazy\"><figcaption>BASIS schools at AZ States</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Fteam%2520at%2520az%2520states!%2520but%2520just%2520out%2520in%2520the%2520widl.jpeg&w=900&output=webp&q=82\" alt=\"Out in the wild at AZ States\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/team%20at%20az%20states!%20but%20just%20out%20in%20the%20widl.jpeg'\"><figcaption>Out in the wild at AZ States</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/team%20working%20at%20az%20states.jpeg\" alt=\"Pit crew at AZ States\" loading=\"lazy\"><figcaption>Pit crew at AZ States</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/group%20dinner%20at%20az%20states.jpeg\" alt=\"Team dinner at AZ States\" loading=\"lazy\"><figcaption>Team dinner at AZ States</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Fteam%2520dinner.png&w=900&output=webp&q=82\" alt=\"Team dinner\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/team%20dinner.png'\"><figcaption>Team dinner</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Fwhole%2520team%2520at%2520queen%2520creek%2520qualifier.jpg&w=900&output=webp&q=82\" alt=\"The whole team at Queen Creek\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/whole%20team%20at%20queen%20creek%20qualifier.jpg'\"><figcaption>The whole team at Queen Creek</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Fdrive%2520team%2520at%2520queen%2520creek%2520qualfieri.jpg&w=900&output=webp&q=82\" alt=\"Drive team at Queen Creek\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/drive%20team%20at%20queen%20creek%20qualfieri.jpg'\"><figcaption>Drive team at Queen Creek</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Fdriver%2520one%2520getting%2520ready%2520for%2520a%2520match.jpg&w=900&output=webp&q=82\" alt=\"Driver one, pre-match\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/driver%20one%20getting%20ready%20for%20a%20match.jpg'\"><figcaption>Driver one, pre-match</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Ffirebytes%2520competing%2520at%2520seaperch.jpg&w=900&output=webp&q=82\" alt=\"Competing at SeaPerch\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/firebytes%20competing%20at%20seaperch.jpg'\"><figcaption>Competing at SeaPerch</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Ffirebytesgrooupphotoat%2520seaperch%2520competitoin.jpg&w=900&output=webp&q=82\" alt=\"Group photo at SeaPerch\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/firebytesgrooupphotoat%20seaperch%20competitoin.jpg'\"><figcaption>Group photo at SeaPerch</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Four%2520seaperch%2520robot.png&w=900&output=webp&q=82\" alt=\"Our SeaPerch robot\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/our%20seaperch%20robot.png'\"><figcaption>Our SeaPerch robot</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Ffirebytes%2520tent.jpg&w=900&output=webp&q=82\" alt=\"Our pit tent\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/firebytes%20tent.jpg'\"><figcaption>Our pit tent</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/FLL%20outreach%20event.jpeg\" alt=\"FLL outreach event\" loading=\"lazy\"><figcaption>FLL outreach event</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/demoingrobottomiddleschoolers.jpeg\" alt=\"Demoing to middle schoolers\" loading=\"lazy\"><figcaption>Demoing to middle schoolers</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Fteam%2520at%2520basis%2520goodyear%2520doing%2520a%2520collaboration%2520event.png&w=900&output=webp&q=82\" alt=\"Collaboration at BASIS Goodyear\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/team%20at%20basis%20goodyear%20doing%20a%20collaboration%20event.png'\"><figcaption>Collaboration at BASIS Goodyear</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/worked%20on%20robot%20at%20brophy.jpeg\" alt=\"Wrenching at Brophy\" loading=\"lazy\"><figcaption>Wrenching at Brophy</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Fchristmas%2520robotics%2520pciture.png&w=900&output=webp&q=82\" alt=\"Christmas robotics\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/christmas%20robotics%20pciture.png'\"><figcaption>Christmas robotics</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Fjudgeschoiceaward.png&w=900&output=webp&q=82\" alt=\"Judges' Choice Award\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/judgeschoiceaward.png'\"><figcaption>Judges' Choice Award</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Fmakerspace.png&w=900&output=webp&q=82\" alt=\"In the makerspace\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/makerspace.png'\"><figcaption>In the makerspace</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Fpicture%2520of%2520robot.jpg&w=900&output=webp&q=82\" alt=\"The robot\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/picture%20of%20robot.jpg'\"><figcaption>The robot</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Fall3dprintedparts%2520for%252025-26%2520season.jpg&w=900&output=webp&q=82\" alt=\"All 3D-printed parts, 25-26 season\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/all3dprintedparts%20for%2025-26%20season.jpg'\"><figcaption>All 3D-printed parts, 25-26 season</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://images.weserv.nl/?url=raw.githubusercontent.com%2Fsuryasreenivasan%2Ffirebytes%2Fmain%2Fpaul%2520hard%2520at%2520work%2520on%2520pvc%2520project.jpg&w=900&output=webp&q=82\" alt=\"Paul hard at work\" loading=\"lazy\" onerror=\"this.onerror=null;this.src='https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/paul%20hard%20at%20work%20on%20pvc%20project.jpg'\"><figcaption>Paul hard at work</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/robotics%20meeting%20at%20pauls%20house%20-%20messy%20floor%20with%20robotics%20parts%20scattered%20everywhere.jpg\" alt=\"Build night at Paul's\" loading=\"lazy\"><figcaption>Build night at Paul's</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/team%20meeting%20in%20house.jpg\" alt=\"Team meeting\" loading=\"lazy\"><figcaption>Team meeting</figcaption></figure>\n      <figure class=\"reveal\"><img src=\"https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/grouprobotics%20phoito%20of%20entire%20team%20main%20one.jpeg\" alt=\"The whole team\" loading=\"lazy\"><figcaption>The whole team</figcaption></figure>\n    </div>\n  </div>\n</section>","join":"<section id=\"join\" style=\"background:linear-gradient(180deg,transparent,rgba(255,255,255,.02),transparent)\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\">\n      <span class=\"eyebrow\">Join the team</span>\n      <h2>Want to build The Phoenix 2.0?</h2>\n      <p>No experience required. Most of our founding members had never touched a competition robot before our rookie season.</p>\n    </div>\n    <div class=\"join reveal\">\n      <div class=\"join-card\">\n        <h3>How to join</h3>\n        <p>Email us and we will send you everything you need to get started.</p>\n        <ol>\n          <li><b>Send an email</b> to <a href=\"mailto:suryasreenivasan0@gmail.com?subject=Joining%20Firebytes%20FTC%2032734\" style=\"color:var(--ember)\">suryasreenivasan0@gmail.com</a></li>\n          <li><b>Get instructions</b> &mdash; we will reply with next steps, forms, and what to expect.</li>\n          <li><b>Come to a meeting</b> and see what we are working on.</li>\n        </ol>\n        <div class=\"btn-row\" style=\"margin-top:24px\">\n          <a class=\"btn btn-primary\" href=\"mailto:suryasreenivasan0@gmail.com?subject=Joining%20Firebytes%20FTC%2032734\">Email us to join &rarr;</a>\n        </div>\n      </div>\n      <div class=\"join-card\">\n        <h3>Meetings</h3>\n        <p>We usually meet over the weekends at a team member&rsquo;s house. Build sessions run long when a competition is close &mdash; bring snacks and a willingness to redo things.</p>\n        <div class=\"spec\" style=\"margin-top:20px\">\n          <span>Weekends</span><span>Team member&rsquo;s house</span><span>All skill levels</span>\n        </div>\n        <h3 style=\"margin-top:28px\">What you will learn</h3>\n        <p>CAD in Onshape, fabrication and assembly, Java programming for FTC, autonomous routines with odometry and vision, and how to run a team like a small engineering organization.</p>\n      </div>\n    </div>\n  </div>\n<div class=\"wrap\" style=\"margin-top:64px\">\n  <div class=\"sec-head reveal\">\n    <span class=\"eyebrow\">Sponsorship</span>\n    <h2>Sponsor tiers</h2>\n    <p>Every dollar goes into parts, registration, and travel. Here is what your support looks like from our side.</p>\n  </div>\n  <div class=\"tiers\">\n      <div class=\"tier bronze reveal\">\n        <span class=\"tier-name\">Bronze</span>\n        <span class=\"tier-price\">$500+</span>\n        <ul><li>Logo on the team website</li><li>Shoutout on our Instagram</li><li>Signed thank-you letter from the team</li></ul>\n      </div>\n      <div class=\"tier silver reveal\">\n        <span class=\"tier-name\">Silver</span>\n        <span class=\"tier-price\">$1,000+</span>\n        <ul><li>Everything in Bronze</li><li>Logo on the robot and pit banner</li><li>Team photo featuring your logo</li><li>Invitation to a build session</li></ul>\n      </div>\n      <div class=\"tier gold reveal\">\n        <span class=\"tier-name\">Gold</span>\n        <span class=\"tier-price\">$3,000+</span>\n        <ul><li>Everything in Silver</li><li>Logo on team apparel and the pit display</li><li>On-site demo for your organization</li><li>Named sponsor on our competition banner</li><li>Quarterly progress reports</li></ul>\n      </div>\n      <div class=\"tier platinum reveal\">\n        <span class=\"tier-name\">Platinum</span>\n        <span class=\"tier-price\">$6,000+</span>\n        <ul><li>Everything in Gold</li><li>Title sponsor placement on the robot and all team materials</li><li>Logo on team jerseys</li><li>Dedicated STEM demo event for your organization</li><li>Early access to our CAD and engineering documentation</li><li>Named in every competition submission</li></ul>\n      </div>\n  </div>\n  <div class=\"btn-row\" style=\"margin-top:28px\"><a class=\"btn btn-primary\" href=\"https://robolyst.org/donate/firebytes\" target=\"_blank\" rel=\"noopener\">Become a sponsor &rarr;</a></div>\n</div>\n</section>","instagram":"<section id=\"instagram\">\n  <div class=\"wrap\">\n    <div class=\"ig-head reveal\">\n      <div class=\"ig-badge\">&#128247;</div>\n      <div>\n        <span class=\"eyebrow\" style=\"margin-bottom:4px\">Follow the build</span>\n        <h2 style=\"font-size:clamp(1.7rem,3.6vw,2.4rem)\">@firebird_robotics</h2>\n      </div>\n      <a class=\"btn btn-ghost\" style=\"margin-left:auto\" href=\"https://www.instagram.com/firebird_robotics/\" target=\"_blank\" rel=\"noopener\">Follow on Instagram</a>\n    </div>\n    <div class=\"reel-strip\" id=\"reel-strip\" style=\"display:none\"></div>\n    <h3 style=\"margin:30px 0 4px;font-size:1.15rem\">Watch us work</h3>\n    <div style=\"margin-top:14px\"><div class=\"vid\">\n      <div class=\"vid-card reveal\"><video src=\"https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/advertising%20joinign%20firebird%20robotics.mp4\" preload=\"metadata\" playsinline></video><div class=\"play\"><span>&#9654;</span></div><div class=\"cap\">Join Firebytes</div></div>\n      <div class=\"vid-card reveal\"><video src=\"https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/most%20popular%20video%20to%20date%20and%20a%20meme%20video.mp4\" preload=\"metadata\" playsinline></video><div class=\"play\"><span>&#9654;</span></div><div class=\"cap\">Our most-watched video</div></div>\n      <div class=\"vid-card reveal\"><video src=\"https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/promotional%20video%20about%20competition%20day%20and%20a%20meme.mp4\" preload=\"metadata\" playsinline></video><div class=\"play\"><span>&#9654;</span></div><div class=\"cap\">Competition day</div></div>\n      <div class=\"vid-card reveal\"><video src=\"https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/robotics%20funny%20real.mp4\" preload=\"metadata\" playsinline></video><div class=\"play\"><span>&#9654;</span></div><div class=\"cap\">Behind the scenes</div></div>\n    </div></div>\n    <p class=\"muted reveal\" style=\"margin-top:22px;font-size:.85rem\">Reels from our season &mdash; build sessions, match days, and outreach.</p>\n  </div>\n</section>","donate":"<section id=\"donate\" style=\"background:linear-gradient(180deg,transparent,rgba(255,255,255,.02),transparent)\">\n  <div class=\"wrap\">\n    <div class=\"donate reveal\">\n      <span class=\"eyebrow\">Support us</span>\n      <h2>Help us keep building.</h2>\n      <p>Robotics is expensive: control hubs, motors, cameras, and structural parts add up fast. Our rookie season ran about $3,300 against a $2,500 budget, and a $1,000 grant from the Argosy Foundation helped close the gap. Every donation goes straight into parts, registration fees, and travel to competitions &mdash; and into keeping this team alive for the students who come after us.</p>\n      <div class=\"btn-row\">\n        <a class=\"btn btn-primary\" href=\"https://robolyst.org/donate/firebytes\" target=\"_blank\" rel=\"noopener\">Donate to Firebytes &rarr;</a>\n        <a class=\"btn btn-ghost\" href=\"mailto:ftc32734@robolyst.org?subject=Sponsoring%20Firebytes%20FTC%2032734\">Talk to us about sponsorship</a>\n      </div>\n    </div>\n  </div>\n</section>","contact":"<section id=\"contact\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\">\n      <span class=\"eyebrow\">Contact</span>\n      <h2>Get in touch</h2>\n      <p>Questions about the team, sponsorship, mentoring, or collaboration? Reach out to us.</p>\n    </div>\n    <div class=\"grid g2 reveal\">\n      <a class=\"contact-card\" href=\"mailto:ftc32734@robolyst.org\"><div class=\"icon\">&#9993;</div><div><b>Team email</b><span>ftc32734@robolyst.org</span></div></a>\n      <a class=\"contact-card\" href=\"mailto:kelsey.cooper@basised.com\"><div class=\"icon\">&#127979;</div><div><b>Coach</b><span>kelsey.cooper@basised.com</span></div></a>\n    </div>\n  </div>\n</section>"};
const SHARED_JS = "\nvar REELS = [];\nvar IG_URL = \"https://www.instagram.com/firebird_robotics/\";\nvar IG_HANDLE = \"@firebird_robotics\";\nvar MODEL_URL = \"/models/robot.step\";\n\n(function(){\n  var nav = document.getElementById('nav');\n  var burger = document.getElementById('burger');\n  var links = document.getElementById('navlinks');\n  window.addEventListener('scroll', function(){\n    if (window.scrollY > 12) nav.classList.add('scrolled'); else nav.classList.remove('scrolled');\n  });\n  burger.addEventListener('click', function(){ links.classList.toggle('open'); });\n  links.addEventListener('click', function(e){ if (e.target.tagName === 'A') links.classList.remove('open'); });\n\n  var els = document.querySelectorAll('.reveal');\n  if ('IntersectionObserver' in window) {\n    var io = new IntersectionObserver(function(entries){\n      entries.forEach(function(en){ if (en.isIntersecting) { en.target.classList.add('in'); io.unobserve(en.target); } });\n    }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });\n    els.forEach(function(el){ io.observe(el); });\n  } else {\n    els.forEach(function(el){ el.classList.add('in'); });\n  }\n\n  function reelNode(item){\n    var a = document.createElement('a');\n    a.className = 'reel';\n    a.href = IG_URL;\n    a.target = '_blank';\n    a.rel = 'noopener';\n    if (item && item.src) {\n      var v = document.createElement('video');\n      v.src = item.src;\n      v.muted = true; v.loop = true; v.autoplay = true; v.playsInline = true;\n      v.setAttribute('muted',''); v.setAttribute('playsinline','');\n      v.preload = 'metadata';\n      a.appendChild(v);\n      var cap = document.createElement('div');\n      cap.className = 'ph';\n      cap.style.background = 'linear-gradient(transparent,rgba(0,0,0,.75))';\n      cap.innerHTML = '<b>' + (item.caption || 'Firebytes') + '</b><span>' + IG_HANDLE + '</span>';\n      a.appendChild(cap);\n      var p = v.play(); if (p && p.catch) p.catch(function(){});\n    } else {\n      var ph = document.createElement('div');\n      ph.className = 'ph';\n      ph.innerHTML = '<span class=\"glyph\">&#9654;</span><b>Watch our reels</b><span>' + IG_HANDLE + '</span>';\n      a.appendChild(ph);\n    }\n    return a;\n  }\n\n  var strip = document.getElementById('reel-strip');\n  if (strip) {\n    var count = REELS.length ? Math.min(REELS.length, 8) : 4;\n    for (var i = 0; i < count; i++) strip.appendChild(reelNode(REELS.length ? REELS[i % REELS.length] : null));\n  }\n\n  var rail = document.getElementById('rail');\n  if (rail) {\n    var inner = document.createElement('div');\n    inner.className = 'rail-inner';\n    var label = document.createElement('div');\n    label.className = 'rail-label';\n    label.textContent = IG_HANDLE;\n    inner.appendChild(label);\n    if (REELS.length) {\n      var scroller = document.createElement('div');\n      scroller.className = 'rail-scroll';\n      var track = document.createElement('div');\n      track.className = 'rail-track';\n      REELS.concat(REELS).forEach(function(item){ track.appendChild(reelNode(item)); });\n      scroller.appendChild(track);\n      inner.appendChild(scroller);\n    } else {\n      inner.appendChild(reelNode(null));\n    }\n    rail.appendChild(inner);\n  }\n})();\n\ndocument.querySelectorAll('.vid-card').forEach(function(card){\n  var v = card.querySelector('video');\n  card.addEventListener('click', function(){\n    if (card.classList.contains('playing')) return;\n    card.classList.add('playing');\n    v.controls = true;\n    var p = v.play();\n    if (p && p.catch) p.catch(function(){});\n  });\n});\n\n(function(){\n  var gal = document.querySelector('.gal');\n  if (!gal) return;\n  var lb = document.createElement('div');\n  lb.className = 'lb';\n  lb.innerHTML = '<button class=\"x\" aria-label=\"Close\">&times;</button><img alt=\"\"><div class=\"cap\"></div>';\n  document.body.appendChild(lb);\n  var big = lb.querySelector('img'), cap = lb.querySelector('.cap');\n  function open(url, label){\n    big.src = url.indexOf('w=900') > -1 ? url.replace('w=900', 'w=1600') : url;\n    cap.textContent = label || '';\n    lb.classList.add('on');\n    document.body.classList.add('lb-open');\n  }\n  function close(){\n    lb.classList.remove('on');\n    document.body.classList.remove('lb-open');\n    big.removeAttribute('src');\n  }\n  gal.addEventListener('click', function(e){\n    var fig = e.target.closest('figure'); if (!fig) return;\n    var im = fig.querySelector('img'); if (!im) return;\n    var c = fig.querySelector('figcaption');\n    open(im.currentSrc || im.src, c ? c.textContent : '');\n  });\n  lb.addEventListener('click', function(e){ if (e.target === lb || e.target.classList.contains('x')) close(); });\n  document.addEventListener('keydown', function(e){ if (e.key === 'Escape') close(); });\n})();";
const VIEWER_JS = "\nimport * as THREE from 'three';\nimport { OrbitControls } from 'three/addons/controls/OrbitControls.js';\nimport { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';\n\nconst MODEL_URLS = [\n  'https://raw.githubusercontent.com/suryasreenivasan/firebytes/main/Current%20Chassis%20V2-compressed.glb',\n  'https://raw.githubusercontent.com/suryasreenivasan/firebytes/master/Current%20Chassis%20V2-compressed.glb'\n];\n\nconst host = document.getElementById('cad-viewer');\nconst statusEl = document.getElementById('cad-status');\nconst spinner = document.getElementById('cad-spinner');\nconst titleEl = document.getElementById('cad-title');\nconst msgEl = document.getElementById('cad-msg');\nconst rotateBtn = document.getElementById('cad-rotate');\nconst resetBtn = document.getElementById('cad-reset');\nconst wireBtn = document.getElementById('cad-wire');\nconst fileInput = document.getElementById('cad-file');\n\nlet renderer, scene, camera, controls, root;\nlet wireframe = false;\nlet homeCam = null;\n\nfunction setStatus(title, msg, spin){\n  titleEl.textContent = title;\n  msgEl.textContent = msg;\n  spinner.style.display = spin ? 'grid' : 'none';\n  statusEl.classList.remove('hide');\n}\nfunction clearStatus(){ statusEl.classList.add('hide'); }\n\nfunction initScene(){\n  renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });\n  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n  renderer.setSize(host.clientWidth, host.clientHeight);\n  renderer.outputColorSpace = THREE.SRGBColorSpace;\n  host.appendChild(renderer.domElement);\n\n  scene = new THREE.Scene();\n  camera = new THREE.PerspectiveCamera(42, host.clientWidth / host.clientHeight, 0.5, 500000);\n  camera.position.set(320, 240, 420);\n\n  controls = new OrbitControls(camera, renderer.domElement);\n  controls.enableDamping = true;\n  controls.dampingFactor = 0.075;\n  controls.autoRotate = true;\n  controls.autoRotateSpeed = 1.1;\n  controls.minDistance = 1;\n  controls.maxDistance = 200000;\n\n  scene.add(new THREE.HemisphereLight(0xdfe9ff, 0x1a2233, 1.15));\n  const key = new THREE.DirectionalLight(0xffffff, 2.0); key.position.set(1, 1.6, 1.1); scene.add(key);\n  const rim = new THREE.DirectionalLight(0xff8a3d, 1.1); rim.position.set(-1.2, -0.4, -0.9); scene.add(rim);\n  const fill = new THREE.DirectionalLight(0x38bdf8, 0.7); fill.position.set(-0.6, 0.8, -1.2); scene.add(fill);\n\n  root = new THREE.Group();\n  scene.add(root);\n\n  window.addEventListener('resize', onResize);\n  animate();\n}\n\nfunction onResize(){\n  if (!renderer) return;\n  const w = host.clientWidth, h = host.clientHeight;\n  if (!w || !h) return;\n  renderer.setSize(w, h);\n  camera.aspect = w / h;\n  camera.updateProjectionMatrix();\n}\n\nfunction animate(){\n  requestAnimationFrame(animate);\n  if (controls) controls.update();\n  if (renderer && scene && camera) renderer.render(scene, camera);\n}\n\nfunction clearModel(){\n  while (root.children.length) {\n    const c = root.children.pop();\n    if (c.geometry) c.geometry.dispose();\n    if (c.material) c.material.dispose();\n  }\n}\n\nfunction fitView(){\n  const box = new THREE.Box3().setFromObject(root);\n  if (box.isEmpty()) return;\n  const size = box.getSize(new THREE.Vector3());\n  const center = box.getCenter(new THREE.Vector3());\n  const radius = Math.max(size.x, size.y, size.z) * 0.5 || 100;\n  const dist = radius / Math.tan((camera.fov * Math.PI) / 360) * 1.5;\n  controls.target.copy(center);\n  camera.position.set(center.x + dist * 0.62, center.y + dist * 0.5, center.z + dist * 0.72);\n  camera.near = Math.max(dist / 1000, 0.1);\n  camera.far = dist * 100;\n  camera.updateProjectionMatrix();\n  controls.minDistance = radius * 0.35;\n  controls.maxDistance = dist * 6;\n  controls.update();\n  homeCam = { pos: camera.position.clone(), target: center.clone() };\n}\n\nfunction addMeshes(meshes){\n  clearModel();\n  let added = 0;\n  meshes.forEach(function(m){\n    const attrs = m.attributes || {};\n    if (!attrs.position || !attrs.position.array) return;\n    const geo = new THREE.BufferGeometry();\n    geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(attrs.position.array), 3));\n    if (attrs.normal && attrs.normal.array) {\n      geo.setAttribute('normal', new THREE.BufferAttribute(new Float32Array(attrs.normal.array), 3));\n    } else {\n      geo.computeVertexNormals();\n    }\n    if (m.index && m.index.array) geo.setIndex(new THREE.BufferAttribute(new Uint32Array(m.index.array), 1));\n    let color = 0xb9c2d0;\n    if (m.color && m.color.length === 3) color = new THREE.Color(m.color[0], m.color[1], m.color[2]).getHex();\n    const mat = new THREE.MeshStandardMaterial({ color: color, metalness: 0.45, roughness: 0.42, wireframe: wireframe, side: THREE.DoubleSide });\n    root.add(new THREE.Mesh(geo, mat));\n    added++;\n  });\n  return added;\n}\n\nasync function loadStepBuffer(buffer, label){\n  setStatus('Parsing CAD', 'Tessellating ' + label + ' — large assemblies can take a moment.', true);\n  await new Promise(function(r){ setTimeout(r, 60); });\n  if (typeof window.occtimportjs !== 'function') {\n    setStatus('3D engine unavailable', 'The STEP parser could not load. Check your connection and reload.', false);\n    return;\n  }\n  const occt = await window.occtimportjs();\n  const result = occt.ReadStepFile(new Uint8Array(buffer), null);\n  if (!result || !result.meshes || !result.meshes.length) {\n    setStatus('Nothing to display', 'That file did not contain any solid geometry.', false);\n    return;\n  }\n  addMeshes(result.meshes);\n  fitView();\n  clearStatus();\n}\n\nasync function loadGltf(url){\n  const loader = new GLTFLoader();\n  try {\n    const mod = await import('three/addons/loaders/DRACOLoader.js');\n    const draco = new mod.DRACOLoader();\n    draco.setDecoderPath('https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/libs/draco/');\n    loader.setDRACOLoader(draco);\n  } catch (e) {}\n  try {\n    const mo = await import('three/addons/libs/meshopt_decoder.module.js');\n    loader.setMeshoptDecoder(mo.MeshoptDecoder);\n  } catch (e) {}\n  const gltf = await loader.loadAsync(url, function(ev){\n    if (ev && ev.total) {\n      var pct = Math.min(99, Math.round((ev.loaded / ev.total) * 100));\n      setStatus('Loading CAD', 'Streaming the chassis - ' + pct + '%', true);\n    }\n  });\n  clearModel();\n  root.add(gltf.scene);\n  root.traverse(function(o){ if (o.isMesh && o.material) o.material.side = THREE.DoubleSide; });\n  fitView();\n  clearStatus();\n}\n\nasync function boot(){\n  initScene();\n  setStatus('Loading 3D engine', 'Fetching the model viewer.', true);\n  for (var i = 0; i < MODEL_URLS.length; i++) {\n    try {\n      setStatus('Loading CAD', 'Fetching the chassis model.', true);\n      await loadGltf(MODEL_URLS[i]);\n      return;\n    } catch (e) {}\n  }\n  try {\n    const res = await fetch(MODEL_URL, { cache: 'force-cache' });\n    if (!res.ok) throw new Error('no model');\n    await loadStepBuffer(await res.arrayBuffer(), 'robot.step');\n  } catch (err) {\n    setStatus('CAD model unavailable', 'The hosted model could not be loaded. Use the Open a STEP file button to preview one from your computer.', false);\n  }\n}\n\nrotateBtn.addEventListener('click', function(){\n  controls.autoRotate = !controls.autoRotate;\n  rotateBtn.classList.toggle('on', controls.autoRotate);\n});\nresetBtn.addEventListener('click', function(){\n  if (homeCam) { camera.position.copy(homeCam.pos); controls.target.copy(homeCam.target); controls.update(); }\n});\nwireBtn.addEventListener('click', function(){\n  wireframe = !wireframe;\n  wireBtn.classList.toggle('on', wireframe);\n  root.traverse(function(o){ if (o.isMesh && o.material) o.material.wireframe = wireframe; });\n});\nfileInput.addEventListener('change', async function(e){\n  const f = e.target.files && e.target.files[0];\n  if (!f) return;\n  try { await loadStepBuffer(await f.arrayBuffer(), f.name); }\n  catch (err) { setStatus('Could not read that file', 'Try exporting the assembly as a .step or .stp file.', false); }\n});\n\n\nboot();\n";
const IMPORTMAP = "<script type=\"importmap\">\n{\"imports\":{\"three\":\"https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js\",\"three/addons/\":\"https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/\"}}\n</script>";
const OCCT = "<script src=\"https://cdn.jsdelivr.net/npm/occt-import-js/dist/occt-import-js.js\"></script>";

function navFor(path){
  var href = path === "/" ? 'href="/"' : 'href="' + path + '"';
  return HEADER.split(href).join(href + ' class="active"');
}

function page(path){
  var p = PAGES[path];
  var body = "";
  for (var i = 0; i < p.body.length; i++) body += SECTIONS[p.body[i]] || "";
  var head = HEAD
    .replace(/<title>[\s\S]*?<\/title>/, "<title>" + p.title + "</title>")
    .replace(/<meta name="description" content="[^"]*">/, '<meta name="description" content="' + p.desc + '">')
    .replace(/<meta property="og:title" content="[^"]*">/, '<meta property="og:title" content="' + p.title + '">')
    .replace(/<meta property="og:description" content="[^"]*">/, '<meta property="og:description" content="' + p.desc + '">');
  var scripts = "<script>" + SHARED_JS + "</script>";
  if (p.viewer) scripts += IMPORTMAP + OCCT + '<script type="module" src="/viewer.js"></script>';
  return head + navFor(path) + body + FOOTER + scripts + "</body></html>";
}

function notFound(){
  return '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Not found — Firebytes</title><link rel="stylesheet" href="/styles.css"></head><body>' + HEADER + '<section><div class="wrap" style="padding:120px 0;text-align:center"><h2>Page not found</h2><p>That page does not exist. <a href="/" style="color:var(--ember)">Back to the home page</a>.</p></div></section>' + FOOTER + '</body></html>';
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const p = url.pathname;
    if (p === "/styles.css") {
      return new Response(CSS, { headers: { "content-type": "text/css;charset=UTF-8", "cache-control": "public, max-age=86400" } });
    }
    if (p === "/viewer.js") {
      return new Response(VIEWER_JS, { headers: { "content-type": "application/javascript;charset=UTF-8", "cache-control": "public, max-age=86400" } });
    }
    if (p === "/robots.txt") {
      return new Response("User-agent: *\nAllow: /\n", { headers: { "content-type": "text/plain" } });
    }
    const key = p.replace(/\/+$/, "") || "/";
    if (!PAGES[key]) {
      return new Response(notFound(), { status: 404, headers: { "content-type": "text/html;charset=UTF-8" } });
    }
    return new Response(page(key), { headers: { "content-type": "text/html;charset=UTF-8", "cache-control": "public, max-age=300" } });
  }
};
